 void BarChecks(){
 var theme=Resources.Load<Mewgic.UI.MewgicTypographySettings>("UI/Typography");Check(theme!=null&&theme.heading!=null&&theme.body!=null,"İki TMP tema fontu bağlı");foreach(var f in new[]{theme.heading,theme.body})foreach(char c in "ÇĞİÖŞÜçğıöşü0123456789")Check(f.HasCharacter(c),"Türkçe/rakam glifi: "+f.name+"/"+c);
 var prefabAsset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/UI/MagicalProgressBar.prefab");var instance=Instantiate(prefabAsset);Check(instance.GetComponentsInChildren<TMPro.TMP_Text>().Length==1&&instance.GetComponents<Mewgic.UI.MagicalBarGraphic>().Length==1,"Prefab tek TMP ve tek çizim bileşeni");DestroyImmediate(instance);var bar=Mewgic.UI.MagicalProgressBar.Create(transform,"TestBar",Vector2.zero,Vector2.one);foreach(var value in new[]{0f,1f,3f,5f,8f,-3f}){bar.SetValue(value,5,animate:false);Check(Mathf.Abs(bar.Percent-Mathf.Clamp01(value/5))<.0001f,"Gerçek dolum: "+value+"/5");}Check(Mathf.Abs(Mewgic.UI.MagicalProgressBar.Normalize(10,20,15)-.5f)<.001f,"Minimum değeri10 olan aralık50%");Check(!float.IsNaN(Mewgic.UI.MagicalProgressBar.Normalize(float.MinValue,float.MaxValue,0)),"Geniş sayısal aralık güvenli");bar.SetValue(0,0);Check(bar.Percent==0&&!float.IsNaN(bar.Percent),"0/0 güvenli");bar.SetValue(float.NaN,5);Check(bar.Percent==0,"NaN güvenli");bar.SetValue(3,5,ready:false);Check(bar.Percent==0,"Yüklenmemiş veri güvenli");bar.SetValue(3,5,isLocked:true);Check(bar.locked&&bar.label.text=="KİLİTLİ","Kilitli durum");bar.SetValue(5,5,isLocked:false);Check(bar.Celebration>0,"Tamamlanma tepkisi");DestroyImmediate(bar.gameObject);
